b. SELECT D, C FROM DEPT_SUMMARY WHERE TOTAL_S > 100000;
c. SELECT D, AVERAGE_S FROM DEPT_SUMMARY WHERE C > ( SELECT C FROM DEPT_SUMMARY WHERE D = 4);
